@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#090d12;--paper:#f0f3f5;--muted:#a1abb4;--orange:#ff5b2e;--cyan:#4ce1df;--line:rgba(255,255,255,.15)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--paper);font-family:'Barlow Condensed',Arial,sans-serif}button{font:inherit;color:inherit}.game-shell{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#10171d}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 50%,transparent 25%,rgba(3,7,10,.23) 74%,rgba(3,6,9,.78) 130%)}.screen-grain{position:absolute;inset:0;pointer-events:none;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.88' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:74px;padding:0 5.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(5,9,13,.83),transparent);font-family:'DM Mono',monospace;font-size:10px;letter-spacing:.11em}.brand{display:flex;gap:12px;align-items:center;color:#fff;text-decoration:none;font-size:11px;font-weight:500;letter-spacing:.14em}.brand b{display:block;color:#9aa3aa;font-size:9px;font-weight:400;margin-top:3px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--orange);color:var(--orange);font-family:'Barlow Condensed';font-size:21px;font-weight:800;transform:skew(-8deg)}.top-meta{color:#c1c7cb}.top-meta i{font-style:normal;color:var(--orange);padding:0 8px}.live-dot{display:inline-block;width:6px;height:6px;background:var(--orange);border-radius:50%;margin-right:8px;box-shadow:0 0 12px var(--orange);vertical-align:1px}.icon-btn{background:none;border:0;color:#d9dfe2;letter-spacing:.1em;font:10px 'DM Mono';cursor:pointer}.icon-btn span{margin-left:6px;color:#929ca4}.menu-screen{position:absolute;inset:74px 0 0;z-index:2;display:grid;grid-template-columns:1fr minmax(390px,39%);align-items:center;padding:0 8.4% 5.2%;gap:8%;background:linear-gradient(90deg,rgba(6,10,14,.68),rgba(7,12,17,.14) 53%,rgba(6,10,14,.62))}.hero-copy{align-self:center;margin-top:-3vh}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.17em;color:#adb6bb;margin:0 0 20px}.eyebrow span{display:inline-block;width:19px;height:1px;background:var(--orange);vertical-align:middle;margin-right:8px}.hero-copy h1{font-size:clamp(72px,9.3vw,140px);line-height:.75;letter-spacing:-.045em;font-weight:900;margin:0;text-shadow:0 6px 35px #040709}.hero-copy h1 em,.result-card h2 em{font-style:normal;color:var(--orange)}.intro{font-size:19px;line-height:1.15;color:#bac2c8;margin:28px 0 27px;letter-spacing:.015em}.primary-btn{height:51px;min-width:242px;padding:0 20px;border:0;background:var(--orange);color:white;display:flex;align-items:center;justify-content:space-between;gap:26px;font-size:13px;font-weight:700;letter-spacing:.12em;cursor:pointer;transition:.2s;box-shadow:0 8px 26px rgba(255,77,39,.2)}.primary-btn:hover{background:#ff744e;transform:translateY(-2px);box-shadow:0 10px 32px rgba(255,77,39,.4)}.primary-btn span{font-size:18px}.best-record{margin-top:30px;font:10px 'DM Mono',monospace;letter-spacing:.08em;color:#9ba5ac}.best-record span{color:#f5c55b;margin-right:7px}.best-record b{font-weight:400;color:#f4f5f6;margin-left:12px}.garage-panel{align-self:center;padding:24px 25px 20px;background:rgba(10,16,21,.78);border:1px solid rgba(255,255,255,.17);backdrop-filter:blur(11px);box-shadow:0 25px 80px #02050770;max-width:480px;width:100%}.section-heading{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:1px solid var(--line);padding-bottom:13px}.section-heading .eyebrow{margin-bottom:5px;color:#9ca8af;font-size:9px}.section-heading h2{margin:0;font-size:24px;line-height:1;font-weight:700;letter-spacing:.035em}.garage-index{font:11px 'DM Mono';color:#fff}.garage-index i{color:#56616a;font-style:normal;margin:0 5px}.car-list{display:grid;gap:7px;padding:13px 0}.car-option{display:grid;grid-template-columns:51px 1fr auto;align-items:center;gap:12px;padding:9px 10px;border:1px solid transparent;background:rgba(255,255,255,.035);cursor:pointer;transition:.18s}.car-option:hover{background:rgba(255,255,255,.08)}.car-option.selected{border-color:rgba(255,91,46,.78);background:linear-gradient(90deg,rgba(255,91,46,.13),rgba(255,255,255,.04))}.car-swatch{height:30px;position:relative;display:grid;place-items:center}.car-swatch:before{content:'';width:42px;height:14px;border-radius:8px 10px 7px 7px;background:var(--car);box-shadow:0 0 16px color-mix(in srgb,var(--car),transparent 40%);transform:skew(-17deg)}.car-swatch:after{content:'';position:absolute;width:18px;height:6px;top:9px;left:18px;border-radius:2px;background:#111b24;transform:skew(-20deg)}.car-name{font-size:15px;line-height:1.05;font-weight:700;letter-spacing:.025em}.car-name small{display:block;color:#8f9aa2;font:8px 'DM Mono';letter-spacing:.08em;margin-top:5px}.car-price{font:9px 'DM Mono';color:#89939b}.car-specs{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;padding:13px 0 12px;border-top:1px solid var(--line)}.car-specs span{font:8px 'DM Mono';letter-spacing:.1em;color:#9da8af}.meter{height:3px;background:#313a41;margin-top:8px}.meter i{height:100%;display:block;width:70%;background:var(--orange);box-shadow:0 0 7px #ff5b2e80;transition:width .25s}.garage-note{font:8px 'DM Mono';letter-spacing:.11em;color:#69747b;margin:4px 0 0}.menu-footer{position:absolute;bottom:23px;left:5.2%;right:5.2%;display:flex;justify-content:space-between;font:9px 'DM Mono';letter-spacing:.13em;color:#919ca3}.menu-footer b{color:var(--orange);font-size:16px;margin-left:9px}.hud{position:absolute;z-index:4;inset:74px 0 0;pointer-events:none}.hud.hidden,.menu-screen.hidden,.result-screen.hidden,.pause-overlay.hidden{display:none}.hud-left{position:absolute;top:26px;left:5.2%;text-shadow:0 2px 8px #000}.race-tag,.score-label,.timer-label{font:9px 'DM Mono';letter-spacing:.12em;color:#c5cdd1}.race-tag i{font-style:normal;color:var(--orange);margin:0 5px}.score-label{margin-top:25px;color:#9ba5aa}.score{font-size:52px;font-weight:800;letter-spacing:.04em;line-height:1.04;font-variant-numeric:tabular-nums}.combo{font:13px 'DM Mono';color:var(--orange);margin-top:2px}.combo span{font-size:9px;color:#d0d4d7;margin-left:5px;letter-spacing:.1em}.hud-right{position:absolute;top:26px;right:5.2%;text-align:right;text-shadow:0 2px 8px #000}.timer{font-size:37px;font-weight:700;line-height:1.1;font-variant-numeric:tabular-nums}.speed-wrap{margin-top:26px;display:grid;grid-template-columns:auto auto;column-gap:8px;align-items:baseline;justify-content:end}.speed-wrap span{font-size:36px;font-weight:800;line-height:1;font-variant-numeric:tabular-nums}.speed-wrap small{font:9px 'DM Mono';color:#b4bdc2}.speed-track{grid-column:1/3;height:3px;background:#89939955;margin-top:7px}.speed-track i{display:block;height:100%;width:0;background:var(--cyan);box-shadow:0 0 9px var(--cyan);transition:width .2s}.pause-btn{position:absolute;right:5.2%;top:150px;pointer-events:auto;border:1px solid #ffffff55;background:#101820a8;width:33px;height:33px;cursor:pointer}.bottom-hint{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);white-space:nowrap;font:9px 'DM Mono';letter-spacing:.13em;color:#c0c8cc;text-shadow:0 2px 8px #000}.bottom-hint span{color:#fff;border:1px solid #ffffff66;padding:6px 8px;margin-right:10px}.bottom-hint b{color:var(--orange);font-weight:400;margin-left:9px}.toast{font-size:30px;font-weight:800;font-style:italic;letter-spacing:.05em;color:white;text-shadow:0 0 22px var(--orange);opacity:0;transform:translateY(12px);transition:.25s}.toast.show{opacity:1;transform:translateY(0)}.touch-controls{display:none;pointer-events:auto}.result-screen,.pause-overlay{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:rgba(5,9,13,.7);backdrop-filter:blur(7px)}.result-card,.pause-overlay>div{width:min(430px,90vw);text-align:center;padding:42px;background:rgba(11,17,22,.94);border:1px solid #ffffff2a;box-shadow:0 30px 90px #0009}.result-card .eyebrow{margin-bottom:15px}.result-card h2,.pause-overlay h2{font-size:58px;line-height:.82;letter-spacing:-.02em;margin:0 0 22px;font-weight:900}.result-caption{font:9px 'DM Mono';letter-spacing:.16em;color:#aab3b8;margin:0 0 1px}.final-score{font-size:57px;font-weight:800;font-variant-numeric:tabular-nums}.result-stats{display:flex;justify-content:space-between;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:13px 0;margin:13px 0 23px;font:9px 'DM Mono';letter-spacing:.08em;color:#9da7ad}.result-stats b{display:block;color:#fff;font-size:14px;margin-top:5px;font-weight:500}.result-card .primary-btn,.pause-overlay .primary-btn{margin:0 auto;min-width:250px}.text-btn{display:block;margin:17px auto 0;border:0;background:none;color:#a5afb5;font:9px 'DM Mono';letter-spacing:.12em;cursor:pointer}.text-btn:hover{color:white}.pause-overlay{z-index:5}.pause-overlay h2{font-size:70px;margin:0 0 25px}.pause-overlay .eyebrow{margin:0 0 10px}.pause-overlay .text-btn{pointer-events:auto}
@media(max-width:850px){.menu-screen{padding-left:5%;padding-right:5%;grid-template-columns:1fr minmax(340px,43%);gap:3%}.hero-copy h1{font-size:clamp(65px,10vw,100px)}.garage-panel{padding:18px}.top-meta{font-size:8px}.brand{font-size:9px}.brand b{font-size:8px}}
@media(max-width:650px){.game-shell{min-height:100dvh}.topbar{height:57px;padding:0 18px}.top-meta{display:none}.icon-btn{font-size:9px}.menu-screen{inset:57px 0 0;display:block;padding:22px 19px 55px;overflow:auto;background:linear-gradient(180deg,rgba(5,9,13,.32),rgba(5,9,13,.75) 35%,rgba(5,9,13,.93))}.hero-copy{margin:8px 0 23px}.hero-copy .eyebrow{font-size:8px;margin-bottom:15px}.hero-copy h1{font-size:clamp(60px,17vw,92px)}.intro{font-size:15px;margin:15px 0 16px}.primary-btn{height:45px;min-width:220px;font-size:11px}.best-record{margin-top:14px;font-size:8px}.garage-panel{padding:14px;margin:0 auto 15px;max-width:460px}.section-heading h2{font-size:21px}.car-list{gap:5px;padding:9px 0}.car-option{padding:6px 8px;grid-template-columns:42px 1fr auto}.car-swatch:before{width:37px}.car-swatch:after{left:15px}.car-name{font-size:13px}.car-name small{font-size:7px;margin-top:3px}.car-specs{padding:9px 0}.garage-note{font-size:7px}.menu-footer{bottom:11px;left:18px;right:18px;font-size:7px}.hud{inset:57px 0 0}.hud-left{top:17px;left:18px}.hud-right{top:17px;right:18px}.score-label{margin-top:16px}.score{font-size:37px}.timer{font-size:28px}.speed-wrap{margin-top:15px}.speed-wrap span{font-size:29px}.pause-btn{right:18px;top:117px}.bottom-hint{display:none}.touch-controls{display:grid;position:absolute;left:16px;right:16px;bottom:max(15px,env(safe-area-inset-bottom));grid-template-columns:repeat(4,1fr);gap:10px}.touch-controls button{height:54px;background:#0a1219b8;border:1px solid #ffffff65;color:#fff;font-size:20px;touch-action:none}.touch-controls button:active{background:var(--orange)}.toast{font-size:23px}.result-card,.pause-overlay>div{padding:33px 22px}.result-card h2{font-size:49px}.final-score{font-size:48px}}
@media(max-height:700px) and (min-width:651px){.menu-screen{padding-bottom:3%;}.hero-copy h1{font-size:clamp(66px,8vw,106px)}.intro{margin:18px 0}.best-record{margin-top:18px}.garage-panel{padding:17px 20px}.car-list{gap:4px;padding:8px 0}.car-option{padding:6px 8px}.menu-footer{bottom:12px}}

(() => {
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const menu = document.querySelector('#menu');
  const hud = document.querySelector('#hud');
  const result = document.querySelector('#result');
  const pauseOverlay = document.querySelector('#pauseOverlay');
  const cars = [
    { name:'Skyline GT-R', sub:'COUPÉ JAPONÉS · 2002', color:'#40a8ff', power:78, grip:71, drift:86, max:410, accel:260, turn:2.85, traction:2.65, price:'R-34' },
    { name:'Muscle V8', sub:'CLÁSICO AMERICANO · NARANJA', color:'#ff642e', power:92, grip:55, drift:96, max:440, accel:285, turn:2.45, traction:1.9, price:'V8' },
    { name:'Supra Turbo', sub:'TUNER JAPONÉS · 1998', color:'#f2c84b', power:83, grip:77, drift:78, max:425, accel:270, turn:3.05, traction:3.0, price:'JZ' },
    { name:'RX-7 Spirit', sub:'ROTARY · EDICIÓN CALLE', color:'#a982ed', power:75, grip:84, drift:81, max:400, accel:245, turn:3.35, traction:3.4, price:'13B' }
  ];
  const W=1200,H=780, cx=600,cy=404,rx=395,ry=248,road=144;
  let selected=0, running=false,paused=false,elapsed=0,score=0,combo=1,bestCombo=1,toastTime=0,last=0,markClock=0;
  let worldScale=1,ox=0,oy=0,dpr=1;
  let keys={},touch={left:false,right:false,gas:false,brake:false};
  let marks=[];
  const player={x:cx,y:cy-ry,vx:0,vy:0,angle:0,color:cars[0].color,trail:0};
  const rivals=[{t:-2.3,color:'#e9e9e9',phase:0},{t:1.2,color:'#f04b42',phase:1.7},{t:2.7,color:'#40d2bd',phase:3.1}];
  let audio=null,osc=null,gain=null,soundOn=false;
  const $=s=>document.querySelector(s);
  function resize(){
    const r=canvas.getBoundingClientRect(); dpr=Math.min(devicePixelRatio||1,2);
    canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);
    worldScale=Math.max(r.width/W,r.height/H);ox=(r.width-W*worldScale)/2;oy=(r.height-H*worldScale)/2;
  }
  window.addEventListener('resize',resize); resize();
  function populateCars(){
    $('#carList').innerHTML=cars.map((c,i)=>`<button class="car-option ${i===selected?'selected':''}" data-car="${i}" style="--car:${c.color}"><span class="car-swatch"></span><span class="car-name">${c.name}<small>${c.sub}</small></span><span class="car-price">${c.price}</span></button>`).join('');
    document.querySelectorAll('.car-option').forEach(el=>el.addEventListener('click',()=>selectCar(+el.dataset.car)));
    updateSpecs();
  }
  function selectCar(i){selected=i;player.color=cars[i].color;document.querySelectorAll('.car-option').forEach((el,j)=>el.classList.toggle('selected',j===i));$('.garage-index').innerHTML=`0${i+1} <i>/</i> 04`;updateSpecs();}
  function updateSpecs(){let c=cars[selected];$('#powerMeter').style.width=c.power+'%';$('#gripMeter').style.width=c.grip+'%';$('#driftMeter').style.width=c.drift+'%';}
  populateCars();
  function formatScore(n){return Math.floor(n).toString().padStart(6,'0')}
  function setToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');toastTime=1.2}
  function begin(){running=true;paused=false;elapsed=0;score=0;combo=1;bestCombo=1;marks=[];player.x=cx;player.y=cy-ry;player.angle=0;player.vx=0;player.vy=0;player.color=cars[selected].color;last=performance.now();menu.classList.add('hidden');result.classList.add('hidden');pauseOverlay.classList.add('hidden');hud.classList.remove('hidden');$('#score').textContent='000000';$('#combo').innerHTML='x1.0 <span>COMBO</span>';if(soundOn)startAudio();}
  function endGame(){running=false;hud.classList.add('hidden');result.classList.remove('hidden');$('#finalScore').textContent=formatScore(score);const record=Math.max(score,+(localStorage.getItem('driftRecord')||0));localStorage.setItem('driftRecord',record);$('#recordStat').textContent=formatScore(record);$('#finalCombo').textContent='x'+bestCombo.toFixed(1);$('#resultTitle').innerHTML=score>record-1?'NOCHE<br><em>DE LEYENDA.</em>':'BUENA<br><em>CORRIDA.</em>';$('#bestScore').textContent=formatScore(record)+' PTS';}
  $('#bestScore').textContent=formatScore(+(localStorage.getItem('driftRecord')||0))+' PTS';
  $('#startBtn').addEventListener('click',begin);$('#againBtn').addEventListener('click',begin);
  $('#garageBtn').addEventListener('click',()=>{result.classList.add('hidden');menu.classList.remove('hidden');});
  function togglePause(){if(!running)return;paused=!paused;pauseOverlay.classList.toggle('hidden',!paused);if(!paused)last=performance.now();}
  $('#pauseBtn').addEventListener('click',togglePause);$('#resumeBtn').addEventListener('click',togglePause);$('#quitBtn').addEventListener('click',()=>{running=false;paused=false;hud.classList.add('hidden');pauseOverlay.classList.add('hidden');menu.classList.remove('hidden');});
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='escape'||k==='p')togglePause();if(k==='enter'&&!running)begin();});
  window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
  document.querySelectorAll('[data-control]').forEach(b=>{const key=b.dataset.control;const down=e=>{e.preventDefault();touch[key]=true};const up=e=>{e.preventDefault();touch[key]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
  function startAudio(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();osc=audio.createOscillator();gain=audio.createGain();osc.type='sawtooth';osc.frequency.value=50;gain.gain.value=0;osc.connect(gain);gain.connect(audio.destination);osc.start()}audio.resume()}catch(e){}}
  $('#soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('#soundBtn').innerHTML=(soundOn?'♫':'×')+' <span>SONIDO</span>';if(soundOn)startAudio();else if(gain)gain.gain.setTargetAtTime(0,audio.currentTime,.08)});
  function input(){return {gas:keys.w||keys.arrowup||keys[' ']||touch.gas,brake:keys.s||keys.arrowdown||touch.brake,left:keys.a||keys.arrowleft||touch.left,right:keys.d||keys.arrowright||touch.right,hand:keys.shift}}
  function nearestTrack(x,y){const a=Math.atan2((y-cy)/ry,(x-cx)/rx);const px=cx+rx*Math.cos(a),py=cy+ry*Math.sin(a);return {x:px,y:py,d:Math.hypot(x-px,y-py),a}}
  function step(dt){
    const c=cars[selected],inp=input();let sp=Math.hypot(player.vx,player.vy);let forwardX=Math.cos(player.angle),forwardY=Math.sin(player.angle);
    const throttle=(inp.gas?1:0)-(inp.brake?1:0);
    player.vx+=forwardX*throttle*c.accel*dt;player.vy+=forwardY*throttle*c.accel*dt;
    if(inp.hand){player.vx*=Math.pow(.985,dt*60);player.vy*=Math.pow(.985,dt*60)}
    const steer=(inp.right?1:0)-(inp.left?1:0);const signed=player.vx*forwardX+player.vy*forwardY;
    if(steer)player.angle+=steer*c.turn*(.26+Math.min(1,sp/180))*(signed< -10?-1:1)*dt;
    forwardX=Math.cos(player.angle);forwardY=Math.sin(player.angle);
    const forward=player.vx*forwardX+player.vy*forwardY;const side=-player.vx*forwardY+player.vy*forwardX;
    const grip=inp.hand?.65:c.traction;
    const damp=Math.min(1,grip*dt);player.vx+=forwardY*side*damp;player.vy-=forwardX*side*damp;
    const drag=Math.pow(inp.gas?.994:.978,dt*60);player.vx*=drag;player.vy*=drag;
    const vmax=c.max;sp=Math.hypot(player.vx,player.vy);if(sp>vmax){player.vx*=vmax/sp;player.vy*=vmax/sp}
    player.x+=player.vx*dt;player.y+=player.vy*dt;
    const tr=nearestTrack(player.x,player.y);
    if(tr.d>road*.5+22){player.x+=(tr.x-player.x)*Math.min(1,dt*4);player.y+=(tr.y-player.y)*Math.min(1,dt*4);player.vx*=.68;player.vy*=.68;setToast('¡VUELVE AL ASFALTO!')}
    const v=Math.hypot(player.vx,player.vy),fx=Math.cos(player.angle),fy=Math.sin(player.angle),sideSpeed=Math.abs(-player.vx*fy+player.vy*fx),dot=(player.vx*fx+player.vy*fy)/Math.max(1,v),driftAngle=Math.acos(Math.max(-1,Math.min(1,dot)));
    const drifting=v>115&&sideSpeed>42&&tr.d<road*.5-2;
    if(drifting){combo=Math.min(9.9,combo+dt*.72);bestCombo=Math.max(bestCombo,combo);score+=(sideSpeed*.18+v*.035)*combo*dt*100;markClock+=dt;if(markClock>.035){markClock=0;const backX=player.x-fx*19,backY=player.y-fy*19;marks.push({x:backX-fy*8,y:backY+fx*8,a:player.angle,life:1});marks.push({x:backX+fy*8,y:backY-fx*8,a:player.angle,life:1});if(marks.length>500)marks.splice(0,2)}if(toastTime<=0&&driftAngle>.36)setToast('¡DERRAPE PERFECTO!')}
    else combo=Math.max(1,combo-dt*1.8);
    marks.forEach(m=>m.life-=dt*.07);marks=marks.filter(m=>m.life>0);
    elapsed+=dt;if(elapsed>=90){elapsed=90;endGame();return}
    $('#score').textContent=formatScore(score);$('#combo').innerHTML='x'+combo.toFixed(1)+' <span>COMBO</span>';$('#timer').textContent='01:'+String(Math.ceil(90-elapsed)).padStart(2,'0');$('#speed').textContent=String(Math.round(v*.48)).padStart(3,'0');$('#speedBar').style.width=Math.min(100,v/c.max*100)+'%';
    if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#toast').classList.remove('show')}
    if(gain&&soundOn){gain.gain.setTargetAtTime(Math.min(.035,v/9000),audio.currentTime,.1);osc.frequency.setTargetAtTime(45+v*.34,audio.currentTime,.1)}
  }

